const req = $input.first().json;
const body = req.body || {};
const auth = String(req.headers?.authorization || '');
const match = auth.match(/^Bearer\s+([A-Za-z0-9]{20,128})$/i);
const adminToken = match ? match[1] : '';
if (!adminToken) return [{ json: { admin_token: '', cliente_id: null, nome_cliente: '', email: '', documento: '', status: 'Lead', whatsapp: '', telefone: '', has_logo: false } }];
const text = (value) => String(value ?? '').trim();
const clienteId = Number(body.cliente_id);
const nome = text(body.nome_cliente);
const email = text(body.email).toLowerCase();
const status = text(body.status);
const whatsapp = text(body.whatsapp).replace(/\D/g, '');
const telefone = text(body.telefone).replace(/\D/g, '');
const rawDocument = text(body.cnpj_cpf || body.cnpj).toUpperCase();
if ([...rawDocument].some((char) => !/[0-9A-Z.\/ -]/.test(char))) throw new Error('Documento fiscal invalido.');
const documento = rawDocument.replace(/[.\/ -]/g, '');
const cpfDigit = (digits, initialWeight) => { let total = 0; for (let i = 0; i < digits.length; i++) total += Number(digits[i]) * (initialWeight - i); const remainder = total % 11; return remainder < 2 ? 0 : 11 - remainder; };
const validCpf = (value) => { if (!/^\d{11}$/.test(value) || /^(\d)\1{10}$/.test(value)) return false; const d1 = cpfDigit(value.slice(0, 9), 10); const d2 = cpfDigit(value.slice(0, 9) + d1, 11); return value.endsWith(`${d1}${d2}`); };
const cnpjDigit = (base, weights) => { const total = [...base].reduce((sum, char, index) => sum + (char.charCodeAt(0) - 48) * weights[index], 0); const remainder = total % 11; return remainder < 2 ? 0 : 11 - remainder; };
const validCnpj = (value) => { if (!/^[0-9A-Z]{12}\d{2}$/.test(value) || (/^\d{14}$/.test(value) && /^(\d)\1{13}$/.test(value))) return false; const w1 = [5,4,3,2,9,8,7,6,5,4,3,2]; const w2 = [6,5,4,3,2,9,8,7,6,5,4,3,2]; const d1 = cnpjDigit(value.slice(0, 12), w1); const d2 = cnpjDigit(value.slice(0, 12) + d1, w2); return value.endsWith(`${d1}${d2}`); };
if (!Number.isSafeInteger(clienteId) || clienteId < 1) throw new Error('Cliente invalido.');
if (nome.length < 2 || nome.length > 150) throw new Error('Nome invalido.');
if (email.length > 100 || !/^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$/.test(email)) throw new Error('E-mail invalido.');
if (!['Ativo', 'Inativo', 'Lead'].includes(status)) throw new Error('Status invalido.');
if (status !== 'Lead' && !documento) throw new Error('CPF/CNPJ obrigatorio para cliente ativo ou inativo.');
if (documento && !validCpf(documento) && !validCnpj(documento)) throw new Error('CPF/CNPJ com digitos verificadores invalidos.');
if (whatsapp && !/^\d{10,15}$/.test(whatsapp)) throw new Error('WhatsApp invalido.');
if (telefone && !/^\d{10,15}$/.test(telefone)) throw new Error('Telefone invalido.');
const binary = $('Receber Edicao').first().binary || {};
return [{ json: { admin_token: adminToken, cliente_id: clienteId, nome_cliente: nome, email, documento, status, whatsapp, telefone, has_logo: Object.keys(binary).length > 0 } }];

const candidates = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
const row = candidates.find((value) => value && typeof value === 'object' && Object.prototype.hasOwnProperty.call(value, 'request_id'));
return [{ json: row ?? { success: 0, result: 'internal_error', should_send: 0, delivery_email: null, reset_token: null, folder_id: null, request_id: null } }];

const binary = $('Receber Edicao').first().binary || {};
const keys = Object.keys(binary);
if (!keys.length) return [];
return [{ json: { folder_id: $('Normalizar Resultado').first().json.folder_id }, binary: { data: binary[keys[0]] } }];
